  "landing.f3text": "हर उत्तर उसके पीछे की योजना या कानूनी स्रोत का हवाला देता है।",
  "landing.how1title": "पूछें",
  "landing.how1text": "अपनी भाषा में अपना प्रश्न टाइप करें या बोलें।",
  "landing.how2title": "मार्गदर्शन पाएँ",
  "landing.how2text": "सहायक स्रोत-आधारित, प्रमाण-समर्थित उत्तर देता है।",
  "landing.how3title": "सत्यापित करें",
  "landing.how3text": "पात्रता, दस्तावेज़ और कानूनी प्रावधानों की जाँच करें।",
  "landing.how4title": "कार्रवाई करें",
  "landing.how4text": "जिन योजनाओं के आप पात्र हैं उन्हें ट्रैक करें या शिकायत दर्ज करें।",
  "landing.how5title": "समाधान",
  "landing.how5text": "अपने अनुरोधों की प्रगति की निगरानी करें और समाधान प्राप्त करें।",
  "landing.howTitle": "यह कैसे काम करता है",
  "landing.trustTitle": "कवरेज",
  "landing.trustText": "PMFBY · फ़सल बीमा · PACS सेवाएँ · वित्तीय साक्षरता · शिकायत निवारण",
  "landing.trust1": "6 भाषाएँ",
  "landing.trust2": "200+ दस्तावेज़",
  "landing.trust3": "प्रमाण-आधारित",
  "landing.trust4": "आवाज़ समर्थित",
  "landing.bentoTitle": "सहकारी शासन के लिए बनाया गया",
  "landing.bentoSubtitle": "हर सुविधा सरकारी योजनाओं और कानूनी मार्गदर्शन को सभी के लिए सुलभ बनाने के लिए डिज़ाइन की गई है।",
  "landing.bento1title": "बहुभाषी",
  "landing.bento1text": "जटिल शासन — योजनाएँ, अधिकार, कानूनी प्रावधान — को स्पष्ट, मातृभाषा उत्तरों में तुरंत अनुवादित करें।",
  "landing.bento2title": "आवाज़ समर्थित",
  "landing.bento2text": "प्रश्न पूछें और उत्तर सुनें — हर साक्षरता स्तर के लिए डिज़ाइन किया गया।",
  "landing.bento3title": "प्रमाण-आधारित",
  "landing.bento3text": "हर उत्तर सत्यापित आधिकारिक स्रोतों और कानूनी संदर्भों पर आधारित।",
  "landing.bento4title": "6 भाषाएँ",
  "landing.bento4text": "हिंदी, गुजराती, मराठी, बंगाली, तमिल और अंग्रेज़ी में पूर्ण समर्थन।",
  "landing.bento5title": "सुरक्षित और निजी",
  "landing.bento5text": "आपकी बातचीत सुरक्षित — कोई डेटा बिक्री नहीं, कोई ट्रैकिंग नहीं।",
  "landing.bento6title": "मार्गदर्शित अगले कदम",
  "landing.bento6text": "पात्रता जाँच से लेकर शिकायत दर्ज करने तक — केवल जानकारी नहीं, बल्कि कार्रवाई योग्य मार्ग।",
  "landing.reviewsTitle": "भारत भर के सहकारी सदस्यों द्वारा विश्वसनीय",

