  "landing.f1title": "বহুভাষিক",
  "landing.f1text": "সরকারি প্রকল্প ও PACS সেবা থেকে সদস্য অধিকার, সুবিধা, আইন ও অভিযোগ — জনসাহায় জটিল সরকারি তথ্যকে পরিষ্কার, নির্ভরযোগ্য উত্তরে রূপান্তরিত করে — আপনার নিজের ভাষায়।",
  "landing.f2title": "ভয়েস-সক্ষম",
  "landing.f2text": "আপনার প্রশ্ন বলুন এবং উত্তরগুলো জোরে শুনুন।",
  "landing.f3title": "প্রমাণ-ভিত্তিক",
  "landing.f3text": "প্রতিটি উত্তর তার পেছনের স্কিম বা আইনি সূত্র উল্লেখ করে।",
  "landing.how1title": "জিজ্ঞাসা করুন",
  "landing.how1text": "আপনার ভাষায় প্রশ্ন টাইপ করুন বা বলুন।",
  "landing.how2title": "নির্দেশনা পান",
  "landing.how2text": "সহকারী সূত্র-ভিত্তিক, প্রমাণ-সমর্থিত উত্তর দিয়ে জবাব দেয়।",
  "landing.how3title": "যাচাই করুন",
  "landing.how3text": "যোগ্যতা, নথি এবং আইনি বিধান যাচাই করুন।",
  "landing.how4title": "ব্যবস্থা নিন",
  "landing.how4text": "আপনি যোগ্য এমন স্কিম ট্র্যাক করুন বা অভিযোগ করুন।",
  "landing.how5title": "সমাধান",
  "landing.how5text": "আপনার অনুরোধের অগ্রগতি পর্যবেক্ষণ করুন এবং সমাধান পান।",
  "landing.howTitle": "এটি কীভাবে কাজ করে",
