  "landing.bentoTitle": "সমবায় শাসনের জন্য তৈরি",
  "landing.bentoSubtitle": "প্রতিটি বৈশিষ্ট্য সরকারি স্কিম এবং আইনি নির্দেশনা সকলের জন্য অ্যাক্সেসযোগ্য করতে ডিজাইন করা।",
  "landing.bento1title": "বহুভাষিক",
  "landing.bento1text": "জটিল শাসন — স্কিম, অধিকার, আইনি বিধান — স্পষ্ট, মাতৃভাষায় উত্তরে তাৎক্ষণিক অনুবাদ।",
  "landing.bento2title": "ভয়েস-সক্ষম",
  "landing.bento2text": "প্রশ্ন জিজ্ঞাসা করুন এবং উত্তর শুনুন — প্রতিটি সাক্ষরতা স্তরের জন্য ডিজাইন।",
  "landing.bento3title": "প্রমাণ-ভিত্তিক",
  "landing.bento3text": "প্রতিটি উত্তর যাচাইকৃত অফিসিয়াল সূত্র এবং আইনি উদ্ধৃতির উপর নির্ভরশীল।",
  "landing.bento4title": "৬টি ভাষা",
  "landing.bento4text": "হিন্দি, গুজরাটি, মারাঠি, বাংলা, তামিল এবং ইংরেজিতে পূর্ণ সমর্থন।",
  "landing.bento5title": "নিরাপদ ও গোপনীয়",
  "landing.bento5text": "আপনার কথোপকথন সুরক্ষিত — কোনো ডেটা বিক্রি নেই, কোনো ট্র্যাকিং নেই।",
  "landing.bento6title": "নির্দেশিত পরবর্তী পদক্ষেপ",
  "landing.bento6text": "যোগ্যতা পরীক্ষা থেকে অভিযোগ দাখিল — শুধু তথ্য নয়, বরং পদক্ষেপযোগ্য পথ।",
