  "landing.f1title": "బహుభాషా",
  "landing.f1text": "ప్రభుత్వ పథకాలు మరియు PACS సేవల నుండి సభ్యుల హక్కులు, ప్రయోజనాలు, చట్టాలు మరియు ఫిర్యాదుల వరకు — జనసహాయ్ సంక్లిష్టమైన అధికారిక సమాచారాన్ని స్పష్టమైన, నమ్మదగిన సమాధానాలుగా మారుస్తుంది — మీ సొంత భాషలో.",
  "landing.f2title": "వాయిస్-ఆధారిత",
