  "landing.badge": "ਸਹਿਕਾਰਤਾ ਮੰਤਰਾਲਾ & PACS ਮਾਰਗਦਰਸ਼ਨ",
  "landing.tagline": "ਸਹਿਕਾਰਤਾ — ਤੁਹਾਡਾ ਬਹੁਭਾਸ਼ਾਈ ਸਹਿਕਾਰੀ ਪ੍ਰਸ਼ਾਸਨ ਸਹਾਇਕ",
  "landing.ctaChat": "ਹੁਣੇ ਚੈਟ ਕਰੋ",
