  "landing.f1title": "ਬਹੁਭਾਸ਼ਾਈ",
  "landing.f1text": "ਸਰਕਾਰੀ ਯੋਜਨਾਵਾਂ ਅਤੇ PACS ਸੇਵਾਵਾਂ ਤੋਂ ਲੈ ਕੇ ਮੈਂਬਰ ਅਧਿਕਾਰਾਂ, ਲਾਭਾਂ, ਕਾਨੂੰਨਾਂ ਅਤੇ ਸ਼ਿਕਾਇਤਾਂ ਤੱਕ — ਜਨਸਹਾਇ ਗੁੰਝਲਦਾਰ ਸਰਕਾਰੀ ਜਾਣਕਾਰੀ ਨੂੰ ਸਾਫ਼, ਭਰੋਸੇਯੋਗ ਜਵਾਬਾਂ ਵਿੱਚ ਬਦਲਦਾ ਹੈ — ਤੁਹਾਡੀ ਆਪਣੀ ਭਾਸ਼ਾ ਵਿੱਚ।",
  "landing.f2title": "ਆਵਾਜ਼-ਸਮਰਥਿਤ",
  "landing.f2text": "ਆਪਣਾ ਸਵਾਲ ਬੋਲੋ ਅਤੇ ਉੱਤਰ ਉੱਚੀ ਸੁਣੋ।",
  "landing.f3title": "ਸਬੂਤ-ਅਧਾਰਿਤ",
  "landing.f3text": "ਹਰ ਉੱਤਰ ਆਪਣੇ ਪਿੱਛੇ ਦੀ ਸਕੀਮ ਜਾਂ ਕਾਨੂੰਨੀ ਸਰੋਤ ਦਾ ਹਵਾਲਾ ਦਿੰਦਾ ਹੈ।",
  "landing.how1title": "ਪੁੱਛੋ",
  "landing.how1text": "ਆਪਣਾ ਸਵਾਲ ਆਪਣੀ ਭਾਸ਼ਾ ਵਿੱਚ ਟਾਈਪ ਕਰੋ ਜਾਂ ਬੋਲੋ।",
  "landing.how2title": "ਮਾਰਗਦਰਸ਼ਨ ਲਓ",
  "landing.how2text": "ਸਹਾਇਕ ਸਰੋਤ-ਆਧਾਰਿਤ, ਸਬੂਤ-ਸਮਰਥਿਤ ਉੱਤਰਾਂ ਨਾਲ ਜਵਾਬ ਦਿੰਦਾ ਹੈ।",
  "landing.how3title": "ਤਸਦੀਕ ਕਰੋ",
  "landing.how3text": "ਯੋਗਤਾ, ਦਸਤਾਵੇਜ਼ ਅਤੇ ਕਾਨੂੰਨੀ ਵਿਵਸਥਾਵਾਂ ਦੀ ਜਾਂਚ ਕਰੋ।",
  "landing.how4title": "ਕਾਰਵਾਈ ਕਰੋ",
  "landing.how4text": "ਜਿਨ੍ਹਾਂ ਸਕੀਮਾਂ ਲਈ ਤੁਸੀਂ ਯੋਗ ਹੋ, ਉਹਨਾਂ ਨੂੰ ਟ੍ਰੈਕ ਕਰੋ ਜਾਂ ਸ਼ਿਕਾਇਤ ਕਰੋ।",
  "landing.how5title": "ਹੱਲ",
  "landing.how5text": "ਆਪਣੀਆਂ ਬੇਨਤੀਆਂ ਦੀ ਪ੍ਰਗਤੀ ਦੀ ਨਿਗਰਾਨੀ ਕਰੋ ਅਤੇ ਹੱਲ ਪ੍ਰਾਪਤ ਕਰੋ।",
