  "landing.bento4text": "હિન્દી, ગુજરાતી, મરાઠી, બંગાળી, તમિલ અને અંગ્રેજીમાં સંપૂર્ણ સપોર્ટ.",
  "landing.bento5title": "સુરક્ષિત અને ખાનગી",
  "landing.bento5text": "તમારી વાતચીત સુરક્ષિત — કોઈ ડેટા વેચાણ નહીં, કોઈ ટ્રેકિંગ નહીં.",
  "landing.bento6title": "માર્ગદર્શિત આગળના પગલાં",
  "landing.bento6text": "પાત્રતા તપાસથી ફરિયાદ નોંધણી સુધી — માત્ર માહિતી નહીં, પરંતુ ક્રિયાપ્રવૃત્તિ માર્ગો.",
  "landing.reviewsTitle": "ભારતભરના સહકારી સભ્યો દ્વારા વિશ્વસનીય",

