  "landing.ctaSchemes": "പദ്ധതികൾ കാണുക",
  "landing.f1title": "ബഹുഭാഷാ",
  "landing.f1text": "സർക്കാർ പദ്ധതികളും PACS സേവനങ്ങളും മുതൽ അംഗ അവകാശങ്ങൾ, ആനുകൂല്യങ്ങൾ, നിയമങ്ങൾ എന്നിവ വരെ — ജനസഹായ് സങ്കീർണ്ണമായ ഔദ്യോഗിക വിവരങ്ങളെ വ്യക്തവും വിശ്വസനീയവുമായ ഉത്തരങ്ങളാക്കി മാറ്റുന്നു — നിങ്ങളുടെ സ്വന്തം ഭാഷയിൽ.",
  "landing.f2title": "ശബ്ദ-പ്രവർത്തനം",
  "landing.f2text": "നിങ്ങളുടെ ചോദ്യം സംസാരിക്കുക, ഉത്തരങ്ങൾ ഉച്ചത്തിൽ കേൾക്കുക.",
  "landing.f3title": "തെളിവ്-അടിസ്ഥാനമാക്കിയുള്ള",
  "landing.f3text": "ഓരോ ഉത്തരവും പിന്നിലുള്ള പദ്ധതി അല്ലെങ്കിൽ നിയമ ഉറവിടം ഉദ്ധരിക്കുന്നു.",
  "landing.how1title": "ചോദിക്കുക",
  "landing.how1text": "നിങ്ങളുടെ ഭാഷയിൽ ചോദ്യം ടൈപ്പ് ചെയ്യുക അല്ലെങ്കിൽ സംസാരിക്കുക.",
  "landing.how2title": "മാർഗ്ഗനിർദ്ദേശം നേടുക",
  "landing.how2text": "സഹായി ഉറവിട-അടിസ്ഥാനമാക്കിയുള്ള, തെളിവ്-പിന്തുണയുള്ള ഉത്തരങ്ങൾ നൽകുന്നു.",
  "landing.how3title": "പരിശോധിക്കുക",
  "landing.how3text": "യോഗ്യത, രേഖകൾ, നിയമ വ്യവസ്ഥകൾ എന്നിവ പരിശോധിക്കുക.",
  "landing.how4title": "പ്രവർത്തിക്കുക",
  "landing.how4text": "നിങ്ങൾക്ക് യോഗ്യതയുള്ള പദ്ധതികൾ ട്രാക്ക് ചെയ്യുക അല്ലെങ്കിൽ പരാതി നൽകുക.",
  "landing.how5title": "പരിഹാരം",
  "landing.how5text": "നിങ്ങളുടെ അഭ്യർത്ഥനകളുടെ പുരോഗതി നിരീക്ഷിക്കുകയും പരിഹാരം നേടുകയും ചെയ്യുക.",
