export const dict: Record<Locale, Record<string, string>> = {
  en, hi, gu, mr, bn, ta, te, kn, pa, or, ml,
};

export function translate(
  locale: string,
  key: string,
  vars?: Vars,
): string {
  const table = (dict as Record<string, Record<string, string>>)[locale] ?? en;
  return interp(table[key] ?? en[key] ?? key, vars);
}
